// Local synthetic evidence and existing synthetic Wrangler output; GET/upload
// transports are injected. No live Cloudflare, Square, D1 or deploy calls.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile,writeFile,mkdtemp,mkdir,readdir,cp,rm,stat,symlink} from 'node:fs/promises';
import path from 'node:path';
import {tmpdir} from 'node:os';
import {createHash} from 'node:crypto';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
const exec=promisify(execFile);
import {preparePrebuilt,deployPrepared,ROLLBACK,SOURCE_SHA} from '../production/prepare-prebuilt-off-release.mjs';
import {identity,profileFromEvidence} from '../production/prepare-off-from-version.mjs';
import {evidenceFromVersionAPI} from '../production/asset-routing-evidence.mjs';
import {evidenceFromPlacementVersion} from '../production/placement-evidence.mjs';
const repo=new URL('../',import.meta.url).pathname,h=b=>createHash('sha256').update(b).digest('hex');
async function files(dir,prefix=''){const out={};for(const d of await readdir(dir,{withFileTypes:true})){if(d.isDirectory())Object.assign(out,await files(path.join(dir,d.name),prefix+d.name+'/'));else out[prefix+d.name]=h(await readFile(path.join(dir,d.name)));}return out;}
async function fixture(t){
 const dir=await mkdtemp(path.join(tmpdir(),'yasoya-prebuilt-test-'));t.after(()=>rm(dir,{recursive:true,force:true}));const root=path.join(dir,'input'),output=path.join(dir,'packet');await mkdir(path.join(root,'dry-run/bundle'),{recursive:true});await mkdir(path.join(root,'release'));
 // Deliberately synthetic prebuilt module: no rebuild, runtime evaluation,
 // external dependencies or persistent /tmp fixture prerequisite.
 const bundle=path.join(root,'dry-run/bundle/storefront-worker.js');await writeFile(bundle,'export class PurchaseCoordinator {}; export default {};\n//# sourceMappingURL=storefront-worker.js.map\n');
 const sources=['production/storefront-worker.js','worker/src/index.js','worker/src/purchase-ledger.js','worker/src/order-mail-outbox.js'];const contents=[];for(const source of sources)contents.push((await exec('git',['show',SOURCE_SHA+':'+source],{cwd:repo,encoding:'utf8',maxBuffer:8*1024*1024})).stdout);
 await writeFile(bundle+'.map',JSON.stringify({version:3,sources:sources.map(p=>path.join(repo,p)),sourcesContent:contents,mappings:'AAAA'}));
 const vars={RUNTIME_TIER:'production',SQUARE_ENVIRONMENT:'production',SQUARE_LOCATION_ID:'LQ693S4H2NBZ8',PRODUCTION_WORKER_NAME:identity.worker,PRODUCTION_PURCHASE_PROTOCOL:'durable-v1',SITE_URL:'https://yasoyahonten.awaiaune.com',MANAGEMENT_ENABLED:'1',PRODUCTION_MANAGEMENT_SCHEMA_READY:'1',PRODUCTION_MANAGEMENT_READ_ENABLED:'1',PRODUCTION_STOREFRONT_ENABLED:'1',PRODUCTION_UNIFIED_PUBLISH_ENABLED:'0',PRODUCTION_STOREFRONT_PUBLISH_ENABLED:'1',PRODUCTION_INVENTORY_WRITER_APPROVAL:'shared-purchase-do-single-writer-v1',PRODUCTION_MANAGEMENT_CATALOG_ENABLED:'0',PRODUCTION_MANAGEMENT_INVENTORY_ENABLED:'1',STOREFRONT_RETIRE_GOLDENROD:'1',PRODUCTION_CHECKOUT_ENABLED:'0',PRODUCTION_MANAGED_CHECKOUT_ENABLED:'0'};
 await cp(new URL('../production/.generated/v53/',import.meta.url),path.join(root,'release/site'),{recursive:true});
 const v={id:ROLLBACK,resources:{script_runtime:{compatibility_date:'2026-08-04',compatibility_flags:[]},bindings:[...Object.entries(vars).map(([name,text])=>({type:'plain_text',name,text})),...['ADMIN_TOKEN','RESEND_API_KEY','SQUARE_ACCESS_TOKEN'].map(name=>({type:'secret_text',name})),{type:'d1',name:'ORDERS_DB',id:identity.database},{type:'durable_object_namespace',name:'PURCHASE_COORDINATOR',namespace_id:identity.namespace,class_name:'PurchaseCoordinator'},{type:'r2_bucket',name:'PRODUCT_IMAGES',bucket_name:identity.bucket},{type:'assets',name:'ASSETS'}]}};
 const routing=evidenceFromVersionAPI({id:ROLLBACK,assets:{config:{run_worker_first:true}}},v),placement=evidenceFromPlacementVersion({id:ROLLBACK},v);
 const e={account:identity.account,worker:identity.worker,versionId:ROLLBACK,activeVersionId:ROLLBACK,traffic:100,routes:[],domains:[{hostname:'yasoyahonten.awaiaune.com',service:identity.worker,zone_id:'a'.repeat(32)}],subdomain:{enabled:true,previews_enabled:false},database:{uuid:identity.database,name:'yasoya-orders'},namespace:{id:identity.namespace,class:'PurchaseCoordinator',script:identity.worker,use_sqlite:true},schedules:[],settings:{placement:{}},assetConfig:routing.config,assetRoutingEvidence:routing,placementEvidence:placement};
 const {config:c,receipt}=profileFromEvidence(v,e,path.join(root,'release/site'));c.main=path.join(repo,'production/storefront-worker.js');await writeFile(path.join(root,'release/off.local.jsonc'),JSON.stringify(c));await writeFile(path.join(root,'evidence.json'),JSON.stringify(receipt));await writeFile(path.join(root,'metadata.json'),JSON.stringify(e));await writeFile(path.join(root,'release/assembly.json'),JSON.stringify({mode:'OFF',changedAssets:['js/checkout-v1.js'],assetSha256:await files(path.join(root,'release/site'))}));await writeFile(path.join(root,'dry-run/diagnostic.json'),JSON.stringify({status:'passed',exitCode:0}));
 const versionFile=path.join(dir,'version.json');await writeFile(versionFile,JSON.stringify(v));const calls=[];let deployed=false;
 const get=async p=>{calls.push(p);assert(!p.includes('/d1/'));const w='/accounts/'+identity.account+'/workers/scripts/'+identity.worker;if(p===w+'/deployments?page=1&per_page=1')return {deployments:[{versions:[{version_id:deployed?'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee':ROLLBACK,percentage:100}]}]};if(p===w+'/versions/'+ROLLBACK)return v;if(p===w+'/settings')return {...e.settings,bindings:v.resources.bindings};if(p===w+'/routes')return e.routes;if(p.includes('/workers/domains?'))return e.domains;if(p===w+'/subdomain')return e.subdomain;if(p===w+'/schedules')return {schedules:e.schedules};if(p==='/accounts/'+identity.account+'/workers/durable_objects/namespaces/'+identity.namespace)return e.namespace;assert.fail('unreviewed endpoint');};
 return {dir,root,output,bundle,v,e,c,get,calls,versionFile,setDeployed:()=>{deployed=true;}};
}
test('preparation freezes the supplied compiled Worker and full assets; originals unchanged and no upload/build',async t=>{
 const f=await fixture(t),before=await files(f.root),r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile});assert.equal(r.status,'PREPARED_NOT_DEPLOYED');assert.equal(r.releaseSha,SOURCE_SHA);assert.equal(r.bundleSha256,h(await readFile(f.bundle)));assert.deepEqual(await files(f.root),before);const c=JSON.parse(await readFile(r.config,'utf8'));assert(c.no_bundle);assert.equal(c.find_additional_modules,false);assert.equal(c.main,path.join(f.output,'bundle/storefront-worker.js'));const beforeConfig=structuredClone(f.c);beforeConfig.main=c.main;beforeConfig.assets.directory=c.assets.directory;beforeConfig.no_bundle=true;beforeConfig.find_additional_modules=false;assert.deepEqual(c,beforeConfig);assert.equal((await stat(f.output)).mode&511,448);assert.equal((await stat(r.config)).mode&511,384);assert(r.deployCommand.endsWith('--approved'));assert(r.rollbackCommand.includes(ROLLBACK));
});
test('changed Version stops preparation before any upload',async t=>{const f=await fixture(t);await assert.rejects(()=>preparePrebuilt({root:f.root,repository:repo,output:f.output},{versionFile:f.versionFile,get:async()=>({deployments:[{versions:[{version_id:'other',percentage:100}]}]})}),/LIVE_VERSION_CHANGED/);});
test('changed live routes stop preparation',async t=>{const f=await fixture(t);await assert.rejects(()=>preparePrebuilt({root:f.root,repository:repo,output:f.output},{versionFile:f.versionFile,get:p=>p.endsWith('/routes')?[{pattern:'other.example/*',zone_id:'a'.repeat(32)}]:f.get(p)}),/LIVE_CONFIGURATION_CHANGED/);});
test('asset drift, extra modules and source-map mismatch stop without deleting inputs',async t=>{
 for(const kind of ['asset','module','map']){const f=await fixture(t);if(kind==='asset')await writeFile(path.join(f.root,'release/site/index.html'),'changed');if(kind==='module')await writeFile(path.join(f.root,'dry-run/bundle/extra.wasm'),'unknown');if(kind==='map'){const m=JSON.parse(await readFile(f.bundle+'.map','utf8'));m.sourcesContent[0]+='\nchanged';await writeFile(f.bundle+'.map',JSON.stringify(m));}await assert.rejects(()=>preparePrebuilt({root:f.root,repository:repo,output:f.output},{versionFile:f.versionFile,get:f.get}),/ASSET_BYTES_CHANGED|ADDITIONAL_MODULES_REQUIRE_REVIEW|BUNDLE_SOURCE_SHA_MISMATCH/);assert((await stat(f.root)).isDirectory());}
});
test('a copied packet cannot deploy without explicit approval',async t=>{const f=await fixture(t),r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile});await assert.rejects(()=>deployPrepared(r.manifest,false,{get:()=>assert.fail(),run:()=>assert.fail()}),/EXPLICIT_APPROVAL_REQUIRED/);});
test('tampering and stale Version block an approved dispatch',async t=>{
 for(const kind of ['asset','bundle','version']){const f=await fixture(t),r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile});if(kind!=='version')await writeFile(path.join(f.output,kind==='asset'?'site/index.html':'bundle/storefront-worker.js'),'changed');await assert.rejects(()=>deployPrepared(r.manifest,true,{expectedManifestHash:r.manifestSha256,get:kind==='version'?async()=>({deployments:[{versions:[{version_id:'other',percentage:100}]}]}):f.get,run:()=>assert.fail('must not upload')}),/FROZEN_ARTIFACT_CHANGED|LIVE_VERSION_CHANGED/);}
});
test('mock approved publication uses only pinned packet config and --no-bundle; duplicate dispatch stops',async t=>{
 const f=await fixture(t),r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile});await symlink('/dev/null',path.join(f.output,'runtime/discard.log'));const commands=[];const done=await deployPrepared(r.manifest,true,{expectedManifestHash:r.manifestSha256,get:f.get,run:async(cmd,args)=>{commands.push({cmd,args});f.setDeployed();return {stdout:'DO_NOT_LOG_BINDINGS',stderr:''};}});assert.equal(commands.length,1);assert.equal(commands[0].cmd,'npx');assert(commands[0].args.includes('--no-bundle'));assert(commands[0].args.includes(r.config));assert(!commands[0].args.includes('--var'));assert.equal(done.status,'OFF_DEPLOYED');await assert.rejects(()=>deployPrepared(r.manifest,true,{expectedManifestHash:r.manifestSha256,get:()=>assert.fail(),run:()=>assert.fail()}),/PREVIOUS_DEPLOY_REQUIRES_REVIEW/);assert(!(await readFile(path.join(f.output,'deployed.json'),'utf8')).includes('DO_NOT_LOG'));
});

test('missing DO export, static imports and dynamic imports are rejected without evaluation',async t=>{
 for(const kind of ['export','static','dynamic']){const f=await fixture(t);let code=await readFile(f.bundle,'utf8');if(kind==='export')code=code.replace('export class PurchaseCoordinator','class PurchaseCoordinator');if(kind==='static')code+='\nimport "https://example.invalid/not-loaded.js";';if(kind==='dynamic')code+='\nimport("https://example.invalid/not-loaded.js");';await writeFile(f.bundle,code);await writeFile(path.join(f.root,'dry-run/diagnostic.json'),JSON.stringify({status:'passed',exitCode:0}));await assert.rejects(()=>preparePrebuilt({root:f.root,repository:repo,output:f.output},{versionFile:f.versionFile,get:f.get}),/BUNDLE_MODULE_REJECTED|DYNAMIC_IMPORT_REQUIRES_REVIEW/);}
});
test('changed live variables stop before dispatch and snapshots work after input files disappear',async t=>{
 const f=await fixture(t),r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile});await rm(f.root,{recursive:true});await assert.rejects(()=>deployPrepared(r.manifest,true,{expectedManifestHash:r.manifestSha256,get:async p=>{const result=await f.get(p);if(p.endsWith('/settings'))return {...result,bindings:result.bindings.map(x=>x.name==='PRODUCTION_CHECKOUT_ENABLED'?{...x,text:'1'}:x)};return result;},run:()=>assert.fail('must not publish')}),/LIVE_SETTINGS_CHANGED/);let published=false;const result=await deployPrepared(r.manifest,true,{expectedManifestHash:r.manifestSha256,get:f.get,run:async()=>{published=true;f.setDeployed();return {stdout:'',stderr:''};}});assert(published);assert.equal(result.status,'OFF_DEPLOYED');
});

test('the approval command pins the manifest hash so manifest edits cannot redefine approved payload hashes',async t=>{
 const f=await fixture(t),r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile});await writeFile(r.manifest,(await readFile(r.manifest,'utf8'))+'\n');await assert.rejects(()=>deployPrepared(r.manifest,true,{expectedManifestHash:r.manifestSha256,get:()=>assert.fail(),run:()=>assert.fail()}),/MANIFEST_HASH_MISMATCH/);
});

test('missing temporary metadata is recovered from current read-only settings and namespace evidence without retrying D1',async t=>{
 const f=await fixture(t);await rm(path.join(f.root,'metadata.json'));const r=await preparePrebuilt({root:f.root,repository:repo,output:f.output},{get:f.get,versionFile:f.versionFile,metadataFile:path.join(f.dir,'missing-metadata.json')});assert.equal(r.status,'PREPARED_NOT_DEPLOYED');assert(f.calls.some(p=>p.includes('/durable_objects/namespaces/')));assert(f.calls.every(p=>!p.includes('/d1/')));const e=JSON.parse(await readFile(path.join(f.output,'metadata.json'),'utf8'));assert(e.localEvidenceReconstruction);assert.equal(e.placementEvidence.config,null);
});
